components.css:
.ds-btn-primary { background: linear-gradient(180deg, #3b82f6 0%, #2563eb 100%); border: 1px solid #1d4ed8; color: #fff; padding: 8px 18px; border-radius: 8px; font: 600 14px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; box-shadow: 0 4px 12px rgba(37,99,235,.25); cursor: pointer; transition: box-shadow .15s, filter .15s; }
.ds-btn-primary:hover { box-shadow: 0 6px 16px rgba(37,99,235,.32); filter: brightness(1.04); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(59,130,246,.35), 0 4px 12px rgba(37,99,235,.25); }
.ds-btn-primary:active { filter: brightness(.96); }

.ds-btn-quiet { background: #fff; border: 1px solid #e6e8eb; color: #1f2329; padding: 8px 16px; border-radius: 8px; font: 400 14px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; cursor: pointer; transition: .15s; }
.ds-btn-quiet:hover { border-color: #2563eb; color: #2563eb; }
.ds-btn-quiet:focus-visible { outline: none; border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,.18); }
.ds-btn-quiet:disabled { opacity: .5; cursor: not-allowed; }

.ds-node-card { background: #fff; border: 1px solid #e6e8eb; border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 4px; min-width: 0; cursor: pointer; user-select: none; transition: border-color .15s, box-shadow .15s, background .15s; }
.ds-node-card:hover { border-color: #93c5fd; }
.ds-node-card.is-sel { border-color: #2563eb; box-shadow: 0 0 0 1px #2563eb inset; }
.ds-node-head { display: flex; align-items: center; gap: 6px; min-width: 0; }
.ds-node-chip { background: #3b82f6; color: #fff; border-radius: 3px; padding: 1px 7px; font: 700 10px/1.5 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; letter-spacing: .4px; }
.ds-node-name { font: 600 13px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #0f172a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-node-lat { font: 400 12px/1.45 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #6b7280; font-variant-numeric: tabular-nums; }

.ds-field-wrap { display: flex; flex-direction: column; gap: 6px; }
.ds-field-label { font: 600 12px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #6b7280; letter-spacing: .2px; }
.ds-field { width: 100%; background: #fff; border: 1px solid #d1d5db; border-radius: 8px; padding: 8px 10px; font: 400 13px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #1f2329; transition: border-color .15s, box-shadow .15s, background .15s; }
.ds-field::placeholder { color: #9ca3af; }
.ds-field:hover { border-color: #93c5fd; }
.ds-field:focus { outline: none; border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59,130,246,.18); }

.ds-pill { display: inline-block; border-radius: 999px; padding: 3px 12px; font: 600 13px/1.5 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; }
.ds-pill-on { background: #dcfce7; color: #166534; }
.ds-pill-off { background: #fee2e2; color: #991b1b; }

.ds-log { background: #0f1115; color: #d6e0ff; border-radius: 10px; padding: 14px; font: 400 12px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace; max-height: 320px; overflow: auto; white-space: pre-wrap; }
.ds-log-t { color: #6b7280; }
.ds-log-lv { color: #3b82f6; font-weight: 700; }
.ds-log-err { color: #dc2626; }

.ds-modal { background: radial-gradient(ellipse at top, rgba(30,64,175,.18), rgba(15,23,42,.55)); border-radius: 10px; padding: 24px; display: flex; justify-content: center; }
.ds-modal-card { background: linear-gradient(180deg, #fff 0%, #fbfcff 100%); border: 1px solid rgba(15,23,42,.08); border-radius: 14px; box-shadow: 0 1px 0 rgba(255,255,255,.6) inset, 0 24px 48px -12px rgba(15,23,42,.35), 0 8px 16px rgba(15,23,42,.18); overflow: hidden; max-width: 420px; }
.ds-modal-head { display: flex; align-items: center; gap: 12px; padding: 18px 22px 14px; border-bottom: 1px solid #eef0f4; background: linear-gradient(180deg, #f8fafc 0%, rgba(248,250,252,0) 100%); }
.ds-modal-icon { display: inline-flex; align-items: center; justify-content: center; width: 36px; height: 36px; border-radius: 10px; background: linear-gradient(135deg, #6366f1 0%, #3b82f6 100%); color: #fff; font-size: 18px; font-weight: 700; box-shadow: 0 4px 12px rgba(59,130,246,.35); flex-shrink: 0; }
.ds-modal-title { margin: 0; font: 700 16px/1.4 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #0f172a; letter-spacing: .2px; }
.ds-modal-sub { margin: 2px 0 0; font: 400 12px/1.5 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #6b7280; }
.ds-modal-body { padding: 16px 22px 20px; font: 400 14px/1.6 'system-ui, "Segoe UI", "Microsoft YaHei", sans-serif'; color: #374151; }
